/**
 * AudioFX - Motor híbrido de alta fidelidad para sonido de paso de página
 * Combina:
 * 1. Web Audio API con AudioBuffer decodificado en memoria (cero latencia, físico)
 * 2. Sintetizador acústico procedural como respaldo en tiempo real
 * 3. Pool de HTML5 Audio con audio precargado
 */

// Audio físico de paso de página en formato WAV 44.1kHz 16-bit PCM base64
const PAGE_FLIP_B64 = "";
const PAGE_FLIP_DATA_URI = "data:audio/wav;base64," + PAGE_FLIP_B64;

export class AudioFX {
  constructor() {
    this.audioCtx = null;
    this.audioBuffer = null;
    this.isMuted = false;
    this.volume = 1.0;
    this.isUnlocked = false;
    this._unlockedOnce = false;
    this._lastPlayTime = 0;

    // 1. Pre-parsear ArrayBuffer desde base64 para decodificación inmediata en Web Audio
    this._rawWavArrayBuffer = null;
    try {
      const binaryString = atob(PAGE_FLIP_B64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      this._rawWavArrayBuffer = bytes.buffer;
    } catch (e) {
      console.warn("Error al decodificar base64 WAV:", e);
    }

    // 2. Pool de elementos HTML5 Audio para fallback secundario
    this.audioPool = [];
    this.poolSize = 4;
    this.poolIndex = 0;
    try {
      for (let i = 0; i < this.poolSize; i++) {
        const a = new Audio(PAGE_FLIP_DATA_URI);
        a.preload = "auto";
        a.volume = this.volume;
        this.audioPool.push(a);
      }
    } catch (e) {
      console.warn("No se pudo inicializar HTML5 Audio pool:", e);
    }

    // 3. Garantizar que siempre inicie desmuteado con volumen al 100%
    this.isMuted = false;
    this.volume = 1.0;
    try {
      localStorage.removeItem("monflip_muted");
      localStorage.removeItem("lumina_flip_muted");
      const savedVol = localStorage.getItem("monflip_volume");
      if (savedVol !== null) {
        this.volume = Math.max(0.2, Math.min(1.0, parseFloat(savedVol)));
      }
    } catch (e) {}

    // 4. Pre-instanciar AudioContext y pre-decodificar el AudioBuffer de inmediato
    this._predecode();
    this._initFetchBackup();
  }

  _predecode() {
    try {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass && !this.audioCtx) {
        this.audioCtx = new AudioContextClass();
      }
      if (this.audioCtx && this._rawWavArrayBuffer && !this.audioBuffer) {
        this.audioCtx.decodeAudioData(
          this._rawWavArrayBuffer.slice(0),
          (decoded) => {
            this.audioBuffer = decoded;
            this.isUnlocked = true;
          },
          () => {}
        );
      }
    } catch (e) {}
  }

  _initFetchBackup() {
    if (typeof fetch !== "undefined") {
      fetch("assets/audio/page-flip.wav")
        .then(res => res.arrayBuffer())
        .then(ab => {
          this._rawWavArrayBuffer = ab;
          if (this.audioCtx && !this.audioBuffer) {
            this.audioCtx.decodeAudioData(ab.slice(0), buf => {
              this.audioBuffer = buf;
              this.isUnlocked = true;
            }, () => {});
          }
        })
        .catch(() => {});
    }
  }

  /**
   * Desbloquea universalmente el hardware de audio en la primera interacción
   */
  unlock() {
    try {
      if (!this.audioCtx) {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (AudioContextClass) {
          this.audioCtx = new AudioContextClass();
        }
      }

      if (this.audioCtx) {
        if (this.audioCtx.state === "suspended") {
          this.audioCtx.resume().catch(() => {});
        }

        // Si tenemos el ArrayBuffer listo pero no hemos decodificado el AudioBuffer
        if (!this.audioBuffer && this._rawWavArrayBuffer) {
          this.audioCtx.decodeAudioData(
            this._rawWavArrayBuffer.slice(0),
            (decoded) => {
              this.audioBuffer = decoded;
              this.isUnlocked = true;
            },
            (err) => {
              console.warn("decodeAudioData error:", err);
            }
          );
        } else if (this.audioBuffer) {
          this.isUnlocked = true;
        }

        // Buffer de desbloqueo de 1 muestra para Safari/iOS
        if (!this._unlockedOnce) {
          try {
            const silent = this.audioCtx.createBuffer(1, 1, 22050);
            const node = this.audioCtx.createBufferSource();
            node.buffer = silent;
            node.connect(this.audioCtx.destination);
            node.start(0);
            this._unlockedOnce = true;
          } catch (e) {}
        }
      }
    } catch (e) {
      console.warn("Error en unlock():", e);
    }
  }

  /**
   * Reproduce el sonido de pasar página garantizando salida acústica inmediata
   */
  playPageTurn(options = {}) {
    if (this.isMuted && !options.force) return;
    if (options.force) {
      this.isMuted = false;
    }

    this.unlock();

    // Debounce de seguridad (120ms) para evitar repeticiones en ráfaga
    const now = Date.now();
    if (!options.force && now - this._lastPlayTime < 120) return;
    this._lastPlayTime = now;

    let played = false;

    // 1. MÉTODO PRINCIPAL: Web Audio API con AudioBuffer físico predecodificado
    if (this.audioCtx) {
      if (this.audioCtx.state === "suspended") {
        this.audioCtx.resume().catch(() => {});
      }

      if (this.audioBuffer) {
        try {
          const src = this.audioCtx.createBufferSource();
          src.buffer = this.audioBuffer;
          // Variación tonal natural (+/- 4%) para realismo orgánico
          src.playbackRate.value = 0.96 + Math.random() * 0.08;

          const gainNode = this.audioCtx.createGain();
          const curVol = Math.max(0.05, Math.min(1.0, this.volume));
          gainNode.gain.setValueAtTime(curVol, this.audioCtx.currentTime);

          src.connect(gainNode);
          gainNode.connect(this.audioCtx.destination);

          src.start(0);
          played = true;
          return;
        } catch (err) {
          console.warn("Error en reproducción AudioBuffer:", err);
        }
      }

      // 2. MÉTODO SECUNDARIO INMEDIATO: Síntesis procedural pura de papel
      if (!played) {
        try {
          this._synthesizeProcedural();
          played = true;
          return;
        } catch (e) {
          console.warn("Error en síntesis procedural:", e);
        }
      }
    }

    // 3. MÉTODO TERCIARIO: Pool HTML5 Audio
    if (!played && this.audioPool && this.audioPool.length > 0) {
      try {
        const audio = this.audioPool[this.poolIndex];
        this.poolIndex = (this.poolIndex + 1) % this.audioPool.length;
        audio.volume = Math.max(0.1, Math.min(1.0, this.volume));
        audio.currentTime = 0;
        const p = audio.play();
        if (p !== undefined) {
          p.catch(() => {});
        }
      } catch (e) {}
    }
  }

  /**
   * Síntesis acústica procedural de alta presencia (fricción de papel + aire)
   */
  _synthesizeProcedural() {
    if (!this.audioCtx) return;
    const ctx = this.audioCtx;
    const now = ctx.currentTime;
    const duration = 0.28;

    const masterGain = ctx.createGain();
    const curVol = Math.max(0.05, Math.min(1.0, this.volume));
    masterGain.gain.setValueAtTime(curVol, now);
    masterGain.connect(ctx.destination);

    // Ruido rosa generado para la fricción de la fibra de papel
    const bufferSize = Math.floor(ctx.sampleRate * duration);
    const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const out = noiseBuffer.getChannelData(0);
    let b0 = 0, b1 = 0, b2 = 0;
    for (let i = 0; i < bufferSize; i++) {
      const white = Math.random() * 2 - 1;
      b0 = 0.99886 * b0 + white * 0.0555179;
      b1 = 0.99332 * b1 + white * 0.0750759;
      b2 = 0.96900 * b2 + white * 0.1538520;
      out[i] = (b0 + b1 + b2 + white * 0.5362) * 0.35;
    }

    const noiseSrc = ctx.createBufferSource();
    noiseSrc.buffer = noiseBuffer;

    // Filtro dinámico deslizante (simula el roce y arqueo de la hoja)
    const bandpass = ctx.createBiquadFilter();
    bandpass.type = "bandpass";
    bandpass.frequency.setValueAtTime(1600, now);
    bandpass.frequency.exponentialRampToValueAtTime(550, now + duration);
    bandpass.Q.setValueAtTime(1.8, now);

    const highpass = ctx.createBiquadFilter();
    highpass.type = "highpass";
    highpass.frequency.setValueAtTime(220, now);

    const envGain = ctx.createGain();
    envGain.gain.setValueAtTime(0.001, now);
    envGain.gain.linearRampToValueAtTime(0.9, now + 0.03);
    envGain.gain.linearRampToValueAtTime(0.001, now + duration);

    noiseSrc.connect(bandpass);
    bandpass.connect(highpass);
    highpass.connect(envGain);
    envGain.connect(masterGain);

    noiseSrc.start(now);
    noiseSrc.stop(now + duration);
  }

  toggleMute() {
    this.isMuted = !this.isMuted;
    try {
      localStorage.setItem("monflip_muted", this.isMuted.toString());
      localStorage.setItem("lumina_flip_muted", this.isMuted.toString());
    } catch (e) {}
    return this.isMuted;
  }

  setVolume(val) {
    this.volume = Math.max(0.1, Math.min(1.0, val));
    for (const a of this.audioPool) {
      a.volume = this.volume;
    }
    try {
      localStorage.setItem("monflip_volume", this.volume.toString());
      localStorage.setItem("lumina_flip_volume", this.volume.toString());
    } catch (e) {}
  }
}
